// Generates packages/core/src/palette.bosses.ts. The import command is its only writer.
import type { Rgb } from '@boss-rush/core';

const HEADER = [
  '// Per-boss colours. GENERATED by the art import tool (brief E): `bun run --filter @boss-rush/tools art:import`.',
  '// Do not edit by hand; re-run the import instead. Keyed by the boss\'s `sprite` prefix.',
  "import type { Rgb } from './palette';",
  '',
];

function channel(value: number): string {
  return `0x${value.toString(16).padStart(2, '0')}`;
}

export function renderPaletteBosses(ramps: Readonly<Record<string, readonly Rgb[]>>): string {
  const keys = Object.keys(ramps).sort();
  if (keys.length === 0) {
    return [...HEADER, 'export const bossRamps: Record<string, readonly Rgb[]> = {};', ''].join('\n');
  }
  const lines = [...HEADER, 'export const bossRamps: Record<string, readonly Rgb[]> = {'];
  for (const key of keys) {
    const colours = ramps[key]!;
    lines.push(`  ${JSON.stringify(key)}: [`);
    for (const [r, g, b] of colours) {
      lines.push(`    [${channel(r)}, ${channel(g)}, ${channel(b)}],`);
    }
    lines.push('  ],');
  }
  lines.push('};', '');
  return lines.join('\n');
}
